const llamada = $('CA9R_Llamar_falla').first().json;
const f = $input.first().json;
const pf = ok => (ok ? 'PASA' : 'FALLA');
const pruebas = [
  { caso: '1 La falla forzada llego al flujo de pruebas como error', resultado: pf(!!llamada.error), detalle: llamada.error ? String(llamada.error.message || llamada.error).slice(0, 120) : 'no hubo error' },
  { caso: '2 El flujo de errores dejo una fila de error reciente en control.ejecuciones', resultado: pf(f.estado === 'error' && f.reciente === true), detalle: JSON.stringify(f) },
  { caso: '3 La fila esta asociada a una automatizacion y marcada como prueba (el monitoreo la ignora)', resultado: pf(f.automatizacion_id === 'A08' && String(f.documento_id || '').startsWith('PRUEBA-ERR-')), detalle: (f.automatizacion_id || '-') + ' / ' + (f.documento_id || '-') },
  { caso: '4 Guarda solo el mensaje de la falla, sin datos', resultado: pf(String(f.detalle_error || '').includes('Falla forzada de la Fase 9')), detalle: f.detalle_error || 'sin detalle' },
];
const pasan = pruebas.filter(x => x.resultado === 'PASA').length;
return [{ json: { resumen: pasan + ' de ' + pruebas.length + ' PASA', pruebas } }];
